#!/bin/sh
# deploy.sh: se niega a desplegar si el repositorio no está impecable
set -eu
rama=$(git symbolic-ref --short -q HEAD) || { echo "HEAD separado: cámbiate a una rama" >&2; exit 1; }
[ "$rama" = main ] || { echo "Solo se despliega desde main (estás en $rama)" >&2; exit 1; }
[ -z "$(git status --porcelain)" ] || { echo "Hay cambios sin confirmar" >&2; exit 1; }
git fetch --quiet origin
set -- $(git rev-list --left-right --count main...origin/main)
[ "$2" -eq 0 ] || { echo "Te faltan $2 commits de origin/main: integra primero" >&2; exit 1; }
[ "$1" -eq 0 ] || { echo "Tienes $1 commits sin publicar: haz push primero" >&2; exit 1; }
echo "Desplegando $(git rev-parse --short HEAD)..."
